"""Evaluate images generated by benchmark.generation."""

import argparse
import json
import os
import re
from pathlib import Path
from tempfile import TemporaryDirectory

import torch
from PIL import Image
from tqdm import tqdm

from benchmark.generation import GenerationEvaluator

NAME_RE = re.compile(r"p(\d+)_s(\d+)\.(?:png|jpg|jpeg)$", re.IGNORECASE)


def prompt_table(jsonl_path):
    """global_index -> prompt, mirroring load_data's indexing (line number)."""
    table = {}
    with open(jsonl_path, "r", encoding="utf-8") as f:
        for i, line in enumerate(f):
            line = line.strip()
            if not line:
                continue
            try:
                item = json.loads(line)
            except json.JSONDecodeError:
                continue
            if "text" in item:
                table[i] = item["text"]
    return table


def pick_device(requested):
    if requested:
        return requested
    if torch.cuda.is_available():
        return "cuda"
    if torch.backends.mps.is_available():
        return "mps"
    return "cpu"


def main():
    p = argparse.ArgumentParser()
    p.add_argument("--image_dir", required=True)
    p.add_argument("--jsonl_path", required=True)
    p.add_argument("--fid_stats", default=None)
    p.add_argument("--device", default=None)
    p.add_argument("--limit", type=int, default=None)
    p.add_argument("--out", default=None, help="defaults to <image_dir>/metrics.json")
    p.add_argument("--overwrite", action="store_true")
    p.add_argument(
        "--seed_slice",
        type=int,
        default=None,
        help="score only images p*_s{NN}.png for this latent slice; "
        "FID is computed on that slice alone. Use when comparing a single fixed latent slice.",
    )
    args = p.parse_args()

    default_name = (
        "metrics.json"
        if args.seed_slice is None
        else f"metrics_s{args.seed_slice:02d}.json"
    )
    out_path = args.out or os.path.join(args.image_dir, default_name)
    if os.path.exists(out_path) and not args.overwrite:
        print(f"{out_path} exists; use --overwrite to recompute.")
        print(json.dumps(json.load(open(out_path)), indent=2))
        return

    device = pick_device(args.device)
    prompts = prompt_table(args.jsonl_path)
    files = []
    seen = set()
    for path in sorted(Path(args.image_dir).iterdir()):
        match = NAME_RE.fullmatch(path.name)
        if not path.is_file() or match is None:
            continue
        index, sample = map(int, match.groups())
        if args.seed_slice is not None and sample != args.seed_slice:
            continue
        if (index, sample) in seen:
            raise ValueError(f"Duplicate image for prompt {index}, sample {sample}")
        seen.add((index, sample))
        files.append((path, index))
    if args.limit:
        files = files[:args.limit]
    if not files:
        raise ValueError(f"No matching generated images in {args.image_dir}")
    if args.fid_stats and not Path(args.fid_stats).is_file():
        raise FileNotFoundError(args.fid_stats)

    print(
        f"device={device}  images={len(files)}  prompts={len(prompts)}"
        + (f"  slice=s{args.seed_slice:02d}" if args.seed_slice is not None else "")
    )

    evaluator = GenerationEvaluator(device=device, fid_stats_path=args.fid_stats)

    for path, index in tqdm(files, desc="scoring"):
        if index not in prompts:
            raise ValueError(f"No prompt on line {index + 1} for {path.name}")
        with Image.open(path) as image:
            evaluator.update_fake(image.convert("RGB"), prompts[index])

    # pytorch-fid opens a directory. Give it exactly the files scored above.
    with TemporaryDirectory(prefix="shiva-fid-") as temp_dir:
        if args.fid_stats:
            for path, _ in files:
                (Path(temp_dir) / path.name.lower()).symlink_to(path.resolve())
        metrics = evaluator.compute(generated_images_dir=temp_dir)
    metrics["_n_images"] = len(files)
    if args.seed_slice is not None:
        metrics["_seed_slice"] = args.seed_slice

    with open(out_path, "w") as f:
        json.dump(metrics, f, indent=2)

    print("\n" + "=" * 46)
    for k, v in metrics.items():
        print(f"{k:<15}: {v}")
    print("=" * 46)
    print(f"written to {out_path}")


if __name__ == "__main__":
    main()
